import { setUpdateState } from './updates';

const CHECK_EVERY_MS = 60 * 60_000;

/**
 * Register the Workbox service worker generated by vite-plugin-pwa (generateSW,
 * autoUpdate: skipWaiting + clientsClaim).
 *
 * We register it ourselves instead of via `virtual:pwa-register` so we don't need
 * `workbox-window` as a direct dependency. Behaviour:
 *  - first install: the SW claims the page -> "ready to work offline" toast;
 *  - update: the new SW activates and takes over -> "new version, Reload" toast,
 *    instead of reloading under the user's thumb mid-chat.
 */
export async function registerServiceWorker(): Promise<void> {
  if (!('serviceWorker' in navigator)) return;
  const sw = navigator.serviceWorker;
  let hasController = !!sw.controller;
  sw.addEventListener('controllerchange', () => {
    if (!hasController) {
      // First install: the new worker just claimed this page.
      hasController = true;
      setUpdateState({ offlineReady: true });
    } else {
      setUpdateState({ needReload: true });
    }
  });
  try {
    const reg = await sw.register(`${import.meta.env.BASE_URL}sw.js`, { scope: import.meta.env.BASE_URL });
    const check = () => {
      if (document.visibilityState === 'visible' && navigator.onLine) void reg.update().catch(() => {});
    };
    setInterval(check, CHECK_EVERY_MS);
    document.addEventListener('visibilitychange', check);
  } catch (e) {
    console.warn('[pwa] service worker registration failed', e);
  }
}
